import notices from "../notices.json";
import { useUi } from "../ui";

/** The open source components that ship and their licences (generated by scripts/licenses.py;
 *  a release check fails if the file is out of date). Attributions a licence asks for are
 *  shown first. */
export function Notices() {
  const { tr } = useUi();
  return (
    <section aria-label={tr("notices")} className="notices">
      <h2>{tr("notices")}</h2>
      <p>{tr("noticesNote")}</p>
      <ul>
        {notices.attributions.map((a) => (
          <li key={a.name}><a href={a.url} rel="noreferrer noopener" target="_blank">{a.name}</a>: <bdi>{a.text}</bdi></li>
        ))}
      </ul>
      <details>
        <summary>{notices.components.length} {tr("noticesCount")}</summary>
        <table>
          <tbody>
            {notices.components.map((c) => (
              <tr key={`${c.ecosystem}:${c.name}`}>
                <td dir="ltr">{c.name}</td><td dir="ltr">{c.version}</td><td dir="ltr">{c.licence}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>
    </section>
  );
}
